CREATE TABLE IF NOT EXISTS schema_migrations (version INT PRIMARY KEY, applied_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS organizations (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL, password_hash VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS technician_categories (user_id BIGINT NOT NULL, category VARCHAR(20) NOT NULL, PRIMARY KEY(user_id,category), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS work_orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(40) NOT NULL UNIQUE, org_id BIGINT NOT NULL, requester_id BIGINT NOT NULL, category VARCHAR(20) NOT NULL, location VARCHAR(200) NOT NULL, description TEXT NOT NULL, status VARCHAR(40) NOT NULL, assignee_id BIGINT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX(org_id,status), FOREIGN KEY(requester_id) REFERENCES users(id), FOREIGN KEY(assignee_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS work_order_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, work_order_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(30) NOT NULL, from_status VARCHAR(40) NOT NULL, to_status VARCHAR(40) NOT NULL, note TEXT NOT NULL, assignee_id BIGINT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(work_order_id) REFERENCES work_orders(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS repair_records (id BIGINT AUTO_INCREMENT PRIMARY KEY, work_order_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, measures TEXT NOT NULL, result TEXT NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(work_order_id) REFERENCES work_orders(id), FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS idempotency_records (org_id BIGINT NOT NULL, user_id BIGINT NOT NULL, idem_key VARCHAR(100) NOT NULL, request_hash CHAR(64) NOT NULL, work_order_id BIGINT NULL, expires_at DATETIME(6) NOT NULL, PRIMARY KEY(org_id,user_id,idem_key));
CREATE TABLE IF NOT EXISTS audit_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NULL, actor_id BIGINT NULL, request_id VARCHAR(64) NOT NULL, action VARCHAR(80) NOT NULL, resource_id BIGINT NULL, outcome VARCHAR(20) NOT NULL, metadata JSON NOT NULL, created_at DATETIME(6) NOT NULL, INDEX(org_id,created_at));
CREATE TABLE IF NOT EXISTS knowledge_materials (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, uploader_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, filename VARCHAR(240) NOT NULL, storage_name CHAR(48) NOT NULL UNIQUE, body LONGTEXT NOT NULL, demo BOOLEAN NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', error_message VARCHAR(200) NOT NULL DEFAULT '', next_generation BIGINT NOT NULL DEFAULT 1, published_generation BIGINT NOT NULL DEFAULT 0, vector_ready BOOLEAN NOT NULL DEFAULT FALSE, vector_collection VARCHAR(100) NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL, INDEX(org_id,id), FOREIGN KEY(uploader_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS knowledge_chunks (id BIGINT AUTO_INCREMENT PRIMARY KEY, material_id BIGINT NOT NULL, generation BIGINT NOT NULL, sequence_no INT NOT NULL, start_char INT NOT NULL, end_char INT NOT NULL, body TEXT NOT NULL, UNIQUE(material_id,generation,sequence_no), FULLTEXT INDEX chunk_text(body) WITH PARSER ngram, FOREIGN KEY(material_id) REFERENCES knowledge_materials(id));
CREATE TABLE IF NOT EXISTS index_jobs (id BIGINT AUTO_INCREMENT PRIMARY KEY, material_id BIGINT NOT NULL, generation BIGINT NOT NULL, status VARCHAR(20) NOT NULL, lease_token CHAR(48) NOT NULL DEFAULT '', lease_until DATETIME(6) NULL, attempts INT NOT NULL DEFAULT 0, error_message VARCHAR(200) NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL, UNIQUE(material_id,generation), INDEX(status,lease_until), FOREIGN KEY(material_id) REFERENCES knowledge_materials(id));
CREATE TABLE IF NOT EXISTS knowledge_generations (material_id BIGINT NOT NULL, generation BIGINT NOT NULL, vector_collection VARCHAR(100) NOT NULL, PRIMARY KEY(material_id,generation), FOREIGN KEY(material_id) REFERENCES knowledge_materials(id));
CREATE TABLE IF NOT EXISTS vector_cleanup_jobs (material_id BIGINT NOT NULL, generation BIGINT NOT NULL, vector_collection VARCHAR(100) NOT NULL, PRIMARY KEY(material_id,generation,vector_collection));
CREATE TABLE IF NOT EXISTS agents (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, seed_key VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, prompt TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 1, UNIQUE(org_id,seed_key), FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS agent_materials (agent_id BIGINT NOT NULL, material_id BIGINT NOT NULL, PRIMARY KEY(agent_id,material_id), FOREIGN KEY(agent_id) REFERENCES agents(id), FOREIGN KEY(material_id) REFERENCES knowledge_materials(id));
CREATE TABLE IF NOT EXISTS conversations (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL DEFAULT '新对话', generation_token CHAR(32) NOT NULL DEFAULT '', generation_until DATETIME(6) NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX(org_id,owner_id,updated_at), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(agent_id) REFERENCES agents(id));
CREATE TABLE IF NOT EXISTS messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, conversation_id BIGINT NOT NULL, turn_token CHAR(32) NOT NULL, role VARCHAR(20) NOT NULL, content MEDIUMTEXT NOT NULL, status VARCHAR(20) NOT NULL, citations JSON NOT NULL, warning VARCHAR(200) NOT NULL DEFAULT '', agent_version BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, INDEX(conversation_id,id), FOREIGN KEY(conversation_id) REFERENCES conversations(id));
